     <a class="skip-link" href="#main-content">Skip to main content</a>
     <main id="main-content">
       <div class="quiz-shell">
         <p class="eyebrow">Multiple-answer quiz</p>
         <h1>Computer Languages Quiz</h1>
         <p class="intro">
           Select every answer that applies for each question, then submit your responses.
         </p>
         <div id="quiz-root"></div>
       </div>
     </main>

     <script>
       const quizQuestions = [
         {
           id: "language-types",
           prompt: "Which of these are programming languages?",
           help: "Choose all answers that are computer programming languages, not markup languages or protocols.",
           choices: ["Python", "HTML", "JavaScript", "HTTP"]
         },
         {
           id: "web-languages",
           prompt: "Which languages commonly run directly in modern web browsers?",
           choices: ["JavaScript", "WebAssembly", "Cascading Style Sheets", "SQL"]
         },
         {
           id: "typed-languages",
           prompt: "Which languages are commonly associated with static typing?",
           choices: ["TypeScript", "Java", "Ruby", "Rust"]
         }
       ];

       function Choice({ questionId, option, index }) {
         const inputId = `${questionId}-choice-${index}`;
         return `
           <label class="choice" for="${inputId}">
             <input id="${inputId}" name="${questionId}" type="checkbox" value="${option}">
             <span class="choice-text">${option}</span>
           </label>
         `;
       }

       function Question({ question, index }) {
         const helpId = `${question.id}-help`;
         const errorId = `${question.id}-error`;
         const describedBy = question.help ? `${helpId} ${errorId}` : errorId;

         return `
           <div class="form-field" data-question-id="${question.id}">
             <fieldset aria-describedby="${describedBy}" aria-invalid="false">
               <legend>${index + 1}. ${question.prompt}</legend>
               ${
                 question.help
                   ? `<p class="help-text" id="${helpId}">${question.help}</p>`
                   : ""
               }
               <div class="choices">
                 ${question.choices
                   .map((option, choiceIndex) =>
                     Choice({ questionId: question.id, option, index: choiceIndex })
                   )
                   .join("")}
               </div>
               <p class="error-message" id="${errorId}">Select at least one answer for this question.</p>
             </fieldset>
           </div>
         `;
       }

       function QuizApp({ questions }) {
         return `
           <form id="quiz-form" novalidate>
             ${questions.map((question, index) => Question({ question, index })).join("")}
             <div class="actions">
               <button type="submit">Submit answers</button>
               <p class="status" id="quiz-status" aria-live="polite"></p>
             </div>
           </form>
         `;
       }

       function getQuestionSelection(questionId) {
         return Array.from(
           document.querySelectorAll(`input[name="${questionId}"]:checked`)
         ).map((input) => input.value);
       }

       function setQuestionValidity(questionId, isValid) {
         const field = document.querySelector(`[data-question-id="${questionId}"]`);
         const fieldset = field.querySelector("fieldset");
         field.classList.toggle("is-invalid", !isValid);
         fieldset.setAttribute("aria-invalid", String(!isValid));
       }

       document.querySelector("#quiz-root").innerHTML = QuizApp({
         questions: quizQuestions
       });

       const form = document.querySelector("#quiz-form");
       const status = document.querySelector("#quiz-status");

       form.addEventListener("change", (event) => {
         if (event.target.matches('input[type="checkbox"]')) {
           const questionId = event.target.name;
           setQuestionValidity(questionId, getQuestionSelection(questionId).length > 0);
           status.textContent = "";
         }
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         const firstIncompleteQuestion = quizQuestions.find(
           (question) => getQuestionSelection(question.id).length === 0
         );

         quizQuestions.forEach((question) => {
           setQuestionValidity(question.id, getQuestionSelection(question.id).length > 0);
         });

         if (firstIncompleteQuestion) {
           status.textContent = "Please answer every question before submitting.";
           document
             .querySelector(`input[name="${firstIncompleteQuestion.id}"]`)
             .focus();
           return;
         }

         const totalSelected = quizQuestions.reduce(
           (count, question) => count + getQuestionSelection(question.id).length,
           0
         );
         status.textContent = `Answers submitted. You selected ${totalSelected} choices across ${quizQuestions.length} questions.`;
       });
     </script>
